% toon0741 -- Illustrate WP Methodology on SlowChirp%	n = 1024;	t = (0:(n-1))./n;	qmf = MakeONFilter('Coiflet',3);	D   = log2(n);%	xi  		= pi/5 .* t;	SlowChirp   = cos(xi .* (1:n));%	WPTour('P',SlowChirp,D,qmf,'SlowChirp');	subplot(2,2,3);	axis([0 500 -10 10]);	drawnow        %   % Part of WaveLab Version 802% Built Sunday, October 3, 1999 8:52:27 AM% This is Copyrighted Material% For Copying permissions see COPYING.m% Comments? e-mail wavelab@stat.stanford.edu%       